import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type Job = {
  id: string; status: 'queued' | 'running' | 'completed' | 'failed'; input: string;
  steps: number; failAttempts: number; attempts: number;
  progress: { completed: number; total: number }; result: { output: string } | null;
  error: string | null; createdAt: string; updatedAt: string;
};

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL,
      steps INTEGER NOT NULL, fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0, result_output TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, available_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status, available_at, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id));
    CREATE TABLE IF NOT EXISTS worker_heartbeat (singleton INTEGER PRIMARY KEY CHECK(singleton=1), at INTEGER NOT NULL);`);
  return db;
}

export function toJob(row: any): Job {
  return {
    id: row.id, status: row.status, input: row.input, steps: row.steps, failAttempts: row.fail_attempts,
    attempts: row.attempts, progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null, createdAt: row.created_at, updatedAt: row.updated_at,
  };
}

export function jobSelect(db: DatabaseSync, id: string): Job | null {
  const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id);
  return row ? toJob(row) : null;
}
