  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const contentType = req.headers['content-type'] ?? '';
    const fields: {field:string;message:string}[] = [];
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({field:'body',message:'Content-Type must be application/json'});
    const rawKey = req.headers['idempotency-key'];
    if (rawKey !== undefined && (Array.isArray(rawKey) || !/^[A-Za-z0-9_-]{1,128}$/.test(rawKey))) fields.push({field:'Idempotency-Key',message:'must contain 1–128 letters, digits, underscores, or hyphens'});
    const key = typeof rawKey === 'string' ? rawKey : undefined;
    let value: any;
    try { value = JSON.parse(await readBody(req)); } catch { fields.push({field:'body',message:'must be valid JSON'}); }
    if (!value || typeof value !== 'object' || Array.isArray(value)) fields.push({field:'body',message:'must be a JSON object'});
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      for (const name of Object.keys(value)) if (!['input','steps','failAttempts'].includes(name)) fields.push({field:name,message:'is not allowed'});
      if (typeof value.input !== 'string') fields.push({field:'input',message:'is required and must be a string'});
      else if (value.input.length < 1 || value.input.length > 1000 || !value.input.trim()) fields.push({field:'input',message:'must be 1–1000 characters and not only whitespace'});
      if (value.steps !== undefined && (!Number.isInteger(value.steps) || value.steps < 1 || value.steps > 20)) fields.push({field:'steps',message:'must be an integer from 1 to 20'});
      if (value.failAttempts !== undefined && (!Number.isInteger(value.failAttempts) || value.failAttempts < 0 || value.failAttempts > 5)) fields.push({field:'failAttempts',message:'must be an integer from 0 to 5'});
    }
    if (fields.length) return err(res, 400, 'invalid_request', 'Request validation failed', fields);
    const input = value.input as string, steps = value.steps ?? 5, failAttempts = value.failAttempts ?? 0;
    const payload = JSON.stringify({input, steps, failAttempts});
    if (key) {
      const old = db.prepare('SELECT payload, job_id FROM idempotency WHERE key=?').get(key) as {payload:string;job_id:string}|undefined;
      if (old) return old.payload === payload ? send(res, 200, jobSelect(db, old.job_id)) : err(res, 409, 'idempotency_conflict', 'Idempotency key was already used with a different payload');
    }
