        if (raced) {
          db.exec('COMMIT');
          return raced.payload === payload ? send(res, 200, jobSelect(db, raced.job_id)) : err(res, 409, 'idempotency_conflict', 'Idempotency key was already used with a different payload');
        }
      }
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at)
        VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0)`).run(id,input,steps,failAttempts,now,now);
      if (key) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key,payload,id);
