  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all();
    return send(res, 200, {jobs: rows.map((r: any) => jobSelect(db,r.id))});
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match && req.method === 'GET') {
    const job = jobSelect(db, decodeURIComponent(match[1]));
    return job ? send(res, 200, job) : err(res, 404, 'not_found', 'Job not found');
  }
