    if (attempt >= 3) db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=?").run(updated,job.id);
    else db.prepare("UPDATE jobs SET status='queued', error=NULL, available_at=?, updated_at=? WHERE id=?").run(Date.now()+400,updated,job.id);
    continue;
  }
  for (let step=1; step<=job.steps; step++) {
    await sleep(100);
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'")
      .run(step,new Date().toISOString(),job.id);
  }
  db.prepare("UPDATE jobs SET status='completed', result_output=?, error=NULL, updated_at=? WHERE id=?")
    .run(job.input.toUpperCase(),new Date().toISOString(),job.id);
}
