<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form">
    <label for="input">Input</label><input id="input" data-testid="job-input" name="input" type="text" required maxlength="1000">
    <label for="steps">Steps</label><input id="steps" data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5">
    <label for="failAttempts">Fail attempts</label><input id="failAttempts" data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0">
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2><section data-testid="job-list" aria-live="polite"></section>
  <script>
    const form=document.querySelector('[data-testid="job-form"]');
    const list=document.querySelector('[data-testid="job-list"]');
    const alertRegion=document.querySelector('[data-testid="form-error"]');
    function render(jobs){list.replaceChildren(...jobs.map(job=>{
      const item=document.createElement('article');item.className='job';item.dataset.testid='job-item';item.dataset.jobId=job.id;
      const head=document.createElement('div');head.className='job-head';
      const title=document.createElement('strong');title.textContent=job.input;
      const status=document.createElement('span');status.dataset.testid='job-status';status.textContent=job.status;
      head.append(title,status);
      const progress=document.createElement('div');progress.className='muted';progress.textContent='Progress: ';
      const progressValue=document.createElement('span');progressValue.dataset.testid='job-progress';progressValue.textContent=job.progress.completed+'/'+job.progress.total;progress.append(progressValue);
      const result=document.createElement('div');result.dataset.testid='job-result';result.textContent=job.result?.output ?? job.error ?? '';
      item.append(head,progress,result);return item;
    }));}
    async function refresh(){try{const response=await fetch('/api/jobs');if(response.ok)render((await response.json()).jobs)}catch(_){}}
    form.addEventListener('submit',async event=>{
      event.preventDefault();alertRegion.textContent='';
      const data=new FormData(form);
      const response=await fetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input:data.get('input'),steps:Number(data.get('steps')),failAttempts:Number(data.get('failAttempts'))})});
      const body=await response.json();
      if(!response.ok){const error=body.error;alertRegion.textContent=error.fields?.map(field=>field.field+': '+field.message).join('; ')||error.message;return;}
      form.elements.input.value='';await refresh();
    });
    refresh();setInterval(refresh,700);
  </script>
</body>
</html>
